const root=document.querySelector('#report');let request=0;
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function href(path){if(typeof path!=='string'||path.startsWith('/')||path.includes('..')||path.includes(':')||path.includes('\\'))throw Error('Invalid artifact link');return 'live-run/'+path}
function link(text,path){const a=el('a',text);a.href=href(path);a.setAttribute('download','');return a}
async function load(){const id=++request;root.textContent='Loading…';try{const res=await fetch('live-run/report.json',{cache:'no-store'});if(!res.ok)throw Error('No exported report. Run python -m worker.export <report-path>, then reload.');const r=await res.json();if(id!==request)return;root.replaceChildren();const summary=el('div',undefined,'summary');summary.append(el('strong',r.verdict),el('p',`Source: ${r.source} · Model: ${r.policy?.model||'none'} · API requests: ${r.policy?.api_requests||0}`),el('p',`Run: ${r.run_id} · ${r.created_at}`),el('p',r.source==='openai'?'This report used the OpenAI adapter. Check the verdict and replay evidence below.':'This is an offline/scripted run. It is not a live model demonstration.'));if(r.error)summary.append(el('p',`${r.error.type}: ${r.error.message}`));summary.append(link('Report JSON','report.json'));if(r.regression)summary.append(el('span',' · '),link('Regression script',r.regression));root.append(summary);const grid=el('div',undefined,'grid');for(const name of ['exploration','replay']){const p=r.phases?.[name];if(!p)continue;const panel=el('section',undefined,'panel');panel.append(el('h2',name==='exploration'?'01 / Exploration':'02 / Independent replay'));const body=el('div',undefined,'body');body.append(el('p',`Status: ${p.status} · Contract: ${p.contract?.status||'not evaluated'}`));if(p.error)body.append(el('p',`${p.error.type}: ${p.error.message}`));for(const d of p.decisions||[]){body.append(el('p',`Step ${d.step}: ${d.decision?.type==='stop'?'Stop':d.decision?.name||d.status} · ${d.observation.quantity} items · ${d.observation.displayed_total}`))}if(p.final)body.append(el('h3',`${p.final.quantity} items · ${p.final.displayed_total}`));if(p.screenshots?.length){const img=el('img');img.src=href(p.screenshots.at(-1));img.alt=name+' final browser state';body.append(img)}const links=el('div',undefined,'links');if(p.trace)links.append(link('Trace ZIP',p.trace));links.append(link('Events',name+'/events.json'));body.append(links,el('p',`Context: ${p.context_id}`,'context'));panel.append(body);grid.append(panel)}root.append(grid)}catch(error){if(id===request)root.textContent=error.message}}
document.querySelector('#refresh').onclick=load;load();
